"use client";

import React, { useRef } from "react";
import { motion, useScroll, useTransform } from "motion/react";
import { Compass, Sparkles } from "lucide-react";
import { cn } from "@/lib/utils";

export interface ScrollParallaxHeroProps
  extends React.HTMLAttributes<HTMLDivElement> {
  title?: string;
  subtitle?: string;
  backgroundImage?: string;
}

export function ScrollParallaxHero({
  title = "THE SUMMIT EXPEDITION",
  subtitle = "High-altitude architectural sanctuary nestled in the Swiss Alps",
  backgroundImage = "https://images.unsplash.com/photo-1506744038136-46273834b3fb?auto=format&fit=crop&w=1200&q=80",
  className,
  ...props
}: ScrollParallaxHeroProps) {
  const containerRef = useRef<HTMLDivElement>(null);

  const { scrollYProgress } = useScroll({
    container: containerRef,
  });

  const backgroundY = useTransform(scrollYProgress, [0, 1], ["0%", "30%"]);
  const backgroundScale = useTransform(scrollYProgress, [0, 1], [1, 1.25]);
  const foregroundY = useTransform(scrollYProgress, [0, 1], ["0%", "-40%"]);
  const textOpacity = useTransform(scrollYProgress, [0, 0.6], [1, 0]);
  const blurFilter = useTransform(
    scrollYProgress,
    [0, 0.8],
    ["blur(0px)", "blur(8px)"]
  );

  return (
    <div
      data-slot="scroll-parallax-hero"
      className={cn(
        "relative w-full max-w-xl mx-auto h-[480px] overflow-hidden rounded-3xl border border-neutral-200 dark:border-neutral-800 bg-neutral-950 shadow-2xl select-none",
        className
      )}
      {...props}
    >
      <div
        ref={containerRef}
        className="h-full overflow-y-auto"
      >
        <div className="relative h-[200vh]">
          {/* Sticky Parallax Viewport */}
          <div className="sticky top-0 h-[480px] overflow-hidden flex items-center justify-center">
            {/* Background Parallax Layer */}
            <motion.div
              style={{
                y: backgroundY,
                scale: backgroundScale,
                filter: blurFilter,
              }}
              className="absolute inset-0 h-full w-full"
            >
              {/* eslint-disable-next-line @next/next/no-img-element */}
              <img
                src={backgroundImage}
                alt="Parallax hero background"
                className="h-full w-full object-cover"
              />
              <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-black/30 to-black/20" />
            </motion.div>

            {/* Foreground Floating Layer */}
            <motion.div
              style={{
                y: foregroundY,
                opacity: textOpacity,
              }}
              className="relative z-10 flex flex-col items-center text-center p-6 text-white max-w-md"
            >
              <div className="inline-flex items-center gap-2 rounded-full border border-white/20 bg-white/10 px-3.5 py-1 text-xs font-mono backdrop-blur-md mb-3 text-pink-300">
                <Sparkles className="h-3.5 w-3.5" />
                <span>Multi-Layer Depth</span>
              </div>

              <h2 className="text-3xl sm:text-4xl font-black tracking-tight uppercase leading-tight">
                {title}
              </h2>

              <p className="text-xs text-white/80 mt-2 leading-relaxed">
                {subtitle}
              </p>
            </motion.div>

            {/* Bottom Scroll Prompt */}
            <div className="absolute bottom-6 left-6 right-6 flex items-center justify-between text-xs text-white/60 font-mono z-10">
              <div className="flex items-center gap-1.5">
                <Compass className="h-4 w-4 text-pink-400" />
                <span>Scroll inside to experience depth parallax</span>
              </div>
              <span className="animate-bounce">↓</span>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
